//! 🎞️ Literal PresentationML owner entities and ordered relations.
use super::super::*;
use semio_framework_os_kernel::sqlite_snapshot::{SqliteDatabase,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::{project_text,reconstruct_text}};
use std::collections::{BTreeMap,BTreeSet};
fn add(total:&mut usize,value:usize)->Result<(),String>{*total=total.checked_add(value).ok_or("PPTX presentation size overflow")?;Ok(())}
fn tick(control:&mut SqliteSnapshotControl<'_>,work:&mut usize,phase:SqliteSnapshotPhase)->Result<(),String>{add(work,1)?;if *work%256==0{control.checkpoint(phase,*work,0)?;}Ok(())}
fn accounted(control:&mut SqliteSnapshotControl<'_>,rows:&mut usize,bytes:&mut usize,row_count:usize,byte_count:usize,work:&mut usize)->Result<(),String>{add(rows,row_count)?;add(bytes,byte_count)?;control.check_rows(*rows)?;control.check_value_bytes(*bytes)?;tick(control,work,SqliteSnapshotPhase::ProjectSnapshot)}
pub(super) fn measure(presentation:&PptxPresentation,control:&mut SqliteSnapshotControl<'_>)->Result<(usize,usize,usize),String>{
 let(mut rows,mut bytes,mut others,mut work)=(1,16,0,0);control.check_rows(presentation.slides.len().checked_add(1).ok_or("PPTX slide count overflow")?)?;
 for slide in &presentation.slides{accounted(control,&mut rows,&mut bytes,1,24,&mut work)?;control.check_rows(rows.checked_add(slide.shapes.len().checked_mul(2).ok_or("PPTX shape count overflow")?).ok_or("PPTX shape count overflow")?)?;
  for shape in &slide.shapes{let(frame,label,kind)=match shape{PptxShape::TextBox{text_frame,..}=>(Some(text_frame.as_slice()),None,"text_box"),PptxShape::Picture{blip_rel_id,..}=>(None,Some(blip_rel_id.as_str()),"picture"),PptxShape::Placeholder{kind,text_frame,..}=>(Some(text_frame.as_slice()),Some(kind.as_str()),"placeholder"),PptxShape::Other{..}=>(None,None,"other")};accounted(control,&mut rows,&mut bytes,2,if kind=="other"{40}else{64},&mut work)?;add(&mut bytes,kind.len())?;add(&mut bytes,label.map_or(0,str::len))?;control.check_value_bytes(bytes)?;
   if let Some(frame)=frame{control.check_rows(rows.checked_add(frame.len()).ok_or("PPTX paragraph count overflow")?)?;for paragraph in frame{accounted(control,&mut rows,&mut bytes,1,24,&mut work)?;control.check_rows(rows.checked_add(paragraph.runs.len()).ok_or("PPTX run count overflow")?)?;for run in &paragraph.runs{accounted(control,&mut rows,&mut bytes,1,40+if run.font_size.is_some(){8}else{0},&mut work)?;add(&mut bytes,run.text.len())?;control.check_value_bytes(bytes)?;}}}
   if matches!(shape,PptxShape::Other{..}){add(&mut others,1)?;}
  }
 }Ok((rows,bytes,others))
}
fn push(database:&mut SqliteDatabase,table:&str,mut values:Vec<SqliteValue>)->Result<i64,String>{let rows=&mut database.table_mut(table)?.rows;let id=i64::try_from(rows.len()+1).map_err(|_|"PPTX entity identity overflow")?;values.insert(0,SqliteValue::Integer(id));rows.push(SqliteRow{rowid:id,values});Ok(id)}
fn component(database:&mut SqliteDatabase,table:&str,id:i64,mut values:Vec<SqliteValue>)->Result<(),String>{values.insert(0,SqliteValue::Integer(id));database.table_mut(table)?.rows.push(SqliteRow{rowid:id,values});Ok(())}
fn number(value:usize)->Result<SqliteValue,String>{Ok(SqliteValue::Integer(i64::try_from(value).map_err(|_|"PPTX ordinal overflow")?))}
fn text(value:&str,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteValue,String>{project_text(control,value).map(SqliteValue::Text)}
pub(super) fn project(presentation:&PptxPresentation,database:&mut SqliteDatabase,first_other:usize,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{
 push(database,"pptx_presentation",vec![SqliteValue::Integer(1)])?;let(mut work,mut other)=(0,first_other);
 for(slide_ordinal,slide)in presentation.slides.iter().enumerate(){tick(control,&mut work,SqliteSnapshotPhase::ProjectSnapshot)?;let slide_id=push(database,"pptx_slide",vec![SqliteValue::Integer(1),number(slide_ordinal)?])?;
  for(shape_ordinal,shape)in slide.shapes.iter().enumerate(){tick(control,&mut work,SqliteSnapshotPhase::ProjectSnapshot)?;let(kind,blip,placeholder,frame,position)=match shape{PptxShape::TextBox{text_frame,position}=>("text_box",None,None,Some(text_frame.as_slice()),Some(position)),PptxShape::Picture{blip_rel_id,position}=>("picture",Some(blip_rel_id.as_str()),None,None,Some(position)),PptxShape::Placeholder{kind,text_frame,position}=>("placeholder",None,Some(kind.as_str()),Some(text_frame.as_slice()),Some(position)),PptxShape::Other{..}=>("other",None,None,None,None)};
   let shape_id=push(database,"pptx_shape",vec![SqliteValue::Integer(slide_id),number(shape_ordinal)?,text(kind,control)?,blip.map(|value|text(value,control)).transpose()?.unwrap_or(SqliteValue::Null),placeholder.map(|value|text(value,control)).transpose()?.unwrap_or(SqliteValue::Null)])?;
   if let Some(position)=position{component(database,"pptx_transform",shape_id,vec![SqliteValue::Integer(position.x),SqliteValue::Integer(position.y),SqliteValue::Integer(position.cx),SqliteValue::Integer(position.cy)])?;}
   else{other=other.checked_add(1).ok_or("PPTX XML shape identity overflow")?;component(database,"pptx_other_shape",shape_id,vec![number(other)?])?;}
   if let Some(frame)=frame{for(paragraph_ordinal,paragraph)in frame.iter().enumerate(){tick(control,&mut work,SqliteSnapshotPhase::ProjectSnapshot)?;let paragraph_id=push(database,"pptx_paragraph",vec![SqliteValue::Integer(shape_id),number(paragraph_ordinal)?])?;for(run_ordinal,run)in paragraph.runs.iter().enumerate(){tick(control,&mut work,SqliteSnapshotPhase::ProjectSnapshot)?;push(database,"pptx_run",vec![SqliteValue::Integer(paragraph_id),number(run_ordinal)?,text(&run.text,control)?,SqliteValue::Integer(i64::from(run.bold)),SqliteValue::Integer(i64::from(run.italic)),run.font_size.map(|value|SqliteValue::Integer(i64::from(value))).unwrap_or(SqliteValue::Null)])?;}}}
  }
 }Ok(())
}
fn identity(row:&SqliteRow,columns:usize)->Result<(),String>{if row.rowid<=0||row.values.len()!=columns||row.integer(0)?!=row.rowid{return Err("PPTX presentation row identity or columns invalid".into());}Ok(())}
type Groups<'a>=BTreeMap<i64,BTreeMap<i64,&'a SqliteRow>>;
fn groups<'a>(database:&'a SqliteDatabase,table:&str,columns:usize,parents:&BTreeSet<i64>,control:&mut SqliteSnapshotControl<'_>,work:&mut usize)->Result<Groups<'a>,String>{
 let mut result=Groups::new();let mut identities=BTreeSet::new();for row in &database.table(table)?.rows{tick(control,work,SqliteSnapshotPhase::ReconstructSnapshot)?;identity(row,columns)?;let parent=row.integer(1)?;let ordinal=row.integer(2)?;if !parents.contains(&parent)||ordinal<0||!identities.insert(row.rowid)||result.entry(parent).or_default().insert(ordinal,row).is_some(){return Err("PPTX ordered entity owner or identity invalid".into());}}
 for rows in result.values(){for(position,ordinal)in rows.keys().enumerate(){tick(control,work,SqliteSnapshotPhase::ReconstructSnapshot)?;if *ordinal!=i64::try_from(position).map_err(|_|"PPTX ordinal overflow")?{return Err("PPTX ordered entity has gaps".into());}}}Ok(result)
}
fn components<'a>(database:&'a SqliteDatabase,table:&str,columns:usize,parents:&BTreeSet<i64>,control:&mut SqliteSnapshotControl<'_>,work:&mut usize)->Result<BTreeMap<i64,&'a SqliteRow>,String>{let mut result=BTreeMap::new();for row in &database.table(table)?.rows{tick(control,work,SqliteSnapshotPhase::ReconstructSnapshot)?;identity(row,columns)?;if !parents.contains(&row.rowid)||result.insert(row.rowid,row).is_some(){return Err("PPTX component owner invalid".into());}}if result.len()!=parents.len(){return Err("PPTX component missing".into());}Ok(result)}
fn boolean(row:&SqliteRow,at:usize)->Result<bool,String>{match row.integer(at)?{0=>Ok(false),1=>Ok(true),_=>Err("PPTX run flag must be boolean".into())}}
pub(super) struct Owner(pub(super) PptxPresentation);
impl Drop for Owner{fn drop(&mut self){use semio_framework_os_kernel::ArtifactSqliteSnapshot;for slide in self.0.slides.drain(..){for shape in slide.shapes{if let PptxShape::Other{node}=shape{semio_s_artifact_stdio_xml::schema::snapshot::XmlSnapshot{schema:String::new(),doc:XmlDocument{root:Some(node),..XmlDocument::default()}}.retire_sqlite_snapshot();}}}}}
pub(super) fn reconstruct(database:&SqliteDatabase,documents:&mut[semio_s_artifact_stdio_xml::schema::snapshot::XmlSnapshot],first_other:usize,control:&mut SqliteSnapshotControl<'_>)->Result<PptxPresentation,String>{
 let root=database.table("pptx_presentation")?.single_row()?;identity(root,2)?;if root.rowid!=1||root.integer(1)?!=1{return Err("PPTX presentation root owner invalid".into());}let mut work=0;
 let slides=groups(database,"pptx_slide",3,&BTreeSet::from([1]),control,&mut work)?;let slide_ids:BTreeSet<_>=slides.values().flat_map(|rows|rows.values().map(|row|row.rowid)).collect();let shapes=groups(database,"pptx_shape",6,&slide_ids,control,&mut work)?;let mut positioned=BTreeSet::new();let mut other_ids=BTreeSet::new();let mut text_ids=BTreeSet::new();
 for row in shapes.values().flat_map(|rows|rows.values()){tick(control,&mut work,SqliteSnapshotPhase::ReconstructSnapshot)?;let kind=row.text(3)?;match kind{"text_box"=>{if row.optional_text(4)?.is_some()||row.optional_text(5)?.is_some(){return Err("PPTX text-box component invalid".into());}text_ids.insert(row.rowid);positioned.insert(row.rowid);},"picture"=>{row.text(4)?;if row.optional_text(5)?.is_some(){return Err("PPTX picture component invalid".into());}positioned.insert(row.rowid);},"placeholder"=>{row.text(5)?;if row.optional_text(4)?.is_some(){return Err("PPTX placeholder component invalid".into());}text_ids.insert(row.rowid);positioned.insert(row.rowid);},"other"=>{if row.optional_text(4)?.is_some()||row.optional_text(5)?.is_some(){return Err("PPTX other component invalid".into());}other_ids.insert(row.rowid);},_=>return Err("PPTX shape discriminant invalid".into())}}
 let transforms=components(database,"pptx_transform",5,&positioned,control,&mut work)?;let others=components(database,"pptx_other_shape",2,&other_ids,control,&mut work)?;let paragraphs=groups(database,"pptx_paragraph",3,&text_ids,control,&mut work)?;let paragraph_ids:BTreeSet<_>=paragraphs.values().flat_map(|rows|rows.values().map(|row|row.rowid)).collect();let runs=groups(database,"pptx_run",7,&paragraph_ids,control,&mut work)?;
 if documents.len()!=first_other.checked_add(other_ids.len()).ok_or("PPTX document count overflow")?{return Err("PPTX XML shape/document cardinality invalid".into());}let mut used_other=first_other;let mut result=Owner(PptxPresentation::default());
 for slide in slides.get(&1).into_iter().flat_map(|rows|rows.values()){result.0.slides.push(PptxSlide::default());let target=result.0.slides.last_mut().unwrap();for shape in shapes.get(&slide.rowid).into_iter().flat_map(|rows|rows.values()){tick(control,&mut work,SqliteSnapshotPhase::ReconstructSnapshot)?;let mut frame=Vec::new();for paragraph in paragraphs.get(&shape.rowid).into_iter().flat_map(|rows|rows.values()){let mut output=PptxParagraph::default();for run in runs.get(&paragraph.rowid).into_iter().flat_map(|rows|rows.values()){tick(control,&mut work,SqliteSnapshotPhase::ReconstructSnapshot)?;let font_size=match run.values[6]{SqliteValue::Null=>None,SqliteValue::Integer(value)=>Some(u32::try_from(value).map_err(|_|"PPTX font size outside unsigned32")?),_=>return Err("PPTX font size must be integer or NULL".into())};output.runs.push(PptxRun{text:reconstruct_text(control,run.text(3)?)?,bold:boolean(run,4)?,italic:boolean(run,5)?,font_size});}frame.push(output);}
 let position=if let Some(row)=transforms.get(&shape.rowid){PptxTransform{x:row.integer(1)?,y:row.integer(2)?,cx:row.integer(3)?,cy:row.integer(4)?}}else{PptxTransform::default()};let output=match shape.text(3)?{"text_box"=>PptxShape::TextBox{text_frame:frame,position},"picture"=>PptxShape::Picture{blip_rel_id:reconstruct_text(control,shape.text(4)?)?,position},"placeholder"=>PptxShape::Placeholder{kind:reconstruct_text(control,shape.text(5)?)?,text_frame:frame,position},"other"=>{let row=others.get(&shape.rowid).ok_or("PPTX other shape component missing")?;used_other=used_other.checked_add(1).ok_or("PPTX other shape count overflow")?;if row.integer(1)?!=i64::try_from(used_other).map_err(|_|"PPTX XML identity overflow")?{return Err("PPTX other shape must own its ordered XML root".into());}let doc=&mut documents[used_other-1];if !doc.schema.is_empty()||doc.doc.declaration.is_some()||doc.doc.doctype.is_some()||!doc.doc.prolog.is_empty()||!doc.doc.epilog.is_empty(){return Err("PPTX other shape XML component has foreign headers".into());}let node=doc.doc.root.take().ok_or("PPTX other shape XML root missing")?;PptxShape::Other{node}},_=>return Err("PPTX shape kind invalid".into())};target.shapes.push(output);}
 }Ok(std::mem::take(&mut result.0))
}
